<script lang="ts">let {data}=$props();const campaignStatus=(value:string)=>({active:'Open for assignments',paused:'Assignments paused',completed:'Completed'}[value]??value.replaceAll('_',' '));const scientificStatus=(value:string)=>({computation:'Computation only',candidate:'Candidate report available',conclusion:'Conclusion report available'}[value]??value.replaceAll('_',' '));const recordStatus=(value:string)=>({open:'Available',checking:'Being checked',complete:'Complete',validation_error:'Check failed',delivery_exhausted:'Needs owner review',importing:'Being imported'}[value]??value.replaceAll('_',' '));</script>
<svelte:head><title>{data.campaign.title} · {campaignStatus(data.campaign.status)} — Voynich@home</title></svelte:head>
<div class="page narrow"><p class="eyebrow">Campaign · {campaignStatus(data.campaign.status)}</p><h1>{data.campaign.title}</h1><p class="lede">{data.campaign.question}</p><span class="badge">Report level: {scientificStatus(data.campaign.scientific_status)}</span>
<section class="panel"><h2>Question and test plan</h2><p>{data.manifest.interpretation}</p><dl><dt>Metric</dt><dd>{data.manifest.metric}</dd><dt>Stopping condition</dt><dd>{data.manifest.stopping_rule}</dd><dt>Previous exposure</dt><dd>{data.manifest.exposure}</dd></dl><a href={data.manifest.protocol_url}>Read the complete protocol ↗</a></section>
<h2>Reports</h2>{#each data.reports as report}<p><a href={'/reports/'+report.digest.slice(7)}>{report.title}</a> · {report.tier}{report.withdrawn?' · withdrawn':''}</p>{:else}<p>No scientific report has been published. Finished work alone does not establish a candidate or conclusion.</p>{/each}
<h2>Reproduction records</h2><p>Each record contains the exact task specification and the server’s independent replay output. Operational errors remain separate from scientific outcomes.</p><a class="button secondary" href={'/api/v1/campaigns/'+data.campaign.id}>Download records (JSON) →</a><p class="small muted" style="margin-top:15px">The JSON download returns 50 records per page; follow its <code>next</code> cursor for the complete campaign. The table below previews the first 100. Select a task ID to download its input and checked result.</p><div class="table-wrap"><table><thead><tr><th>Task ID</th><th>Execution state</th></tr></thead><tbody>{#each data.records as record}<tr><td><a href={'/api/v1/records/'+encodeURIComponent(record.id)}><code>{record.id}</code></a></td><td>{recordStatus(record.state)}</td></tr>{/each}</tbody></table></div>
<details><summary>Versioned campaign manifest</summary><p class="small"><code>{data.campaign.manifest_digest}</code></p><pre>{JSON.stringify(data.manifest,null,2)}</pre></details></div>
